		'sections'  => array(
			array( 'h' => 'מי זכאי ומה בודקים', 'p' => 'ארבעה תנאים מצטברים. תושב ישראל בגיל 18 עד גיל הפרישה. נכות רפואית של 60% לפחות, או 40% כשליקוי אחד הוא 25% ומעלה. אובדן כושר השתכרות של 50% לפחות, כלומר צמצום ממשי ביכולת לעבוד. ותנאי הכנסה: אין הכנסה מעבודה במשך 90 ימים רצופים לפחות, או שההכנסה אינה עולה על 8,261 ש"ח לחודש בשנת 2026.' ),
			array( 'h' => 'איך נקבעת הדרגה וכמה מקבלים', 'p' => 'הוועדה הרפואית קובעת את אחוזי הנכות הרפואית, ופקיד התביעות קובע את דרגת אי-הכושר: 60%, 65%, 74% או 100%, כש-75% נחשבת דרגה מלאה. הקצבה החודשית ב-2026: דרגה מלאה 4,711 ש"ח, 74% מזכה ב-3,211 ש"ח, 65% ב-2,894 ש"ח ו-60% ב-2,718 ש"ח. לקצבה מתווספת תוספת בעד בן או בת זוג שהכנסתם אינה עולה על 7,848 ש"ח ברוטו, ובעד שני הילדים הראשונים.' ),
			array( 'h' => 'מה מביאים ומה קורה אחרי ההגשה', 'p' => 'התביעה מוגשת למוסד לביטוח לאומי, גם בטופס מקוון, עם כל המסמכים הרפואיים. אחר כך נשלח זימון לוועדה, ולעתים המסמכים מספיקים בלי להופיע. הזכאות מתחילה בתום 90 יום מהתאריך הקובע, היום שבו החל אי-הכושר, ואם נקבעו 100% לשישה חודשים לפחות, כבר מהיום ה-31. תשלום רטרואקטיבי מוגבל ל-12 חודשים לפני ההגשה. הקצבה אינה תלויה באשם, ובמקביל אפשר לתבוע את המזיק, בכפוף לזכות השיפוי של המוסד לפי סעיף 328. מוקד 6050 כוכבית.' ),
